#include <vector>

using namespace std;

class stringx
{
  char data[8];
public:
  stringx();
  bool operator<(const stringx&) const;
};

__asm__(".equ __7stringx, 0x0034D3E0");

typedef list<int> vm_symbol_list;

class so_data_block
{
  char* buffer;
  int size_value;
  int max_size;
public:
  so_data_block() : buffer(0), size_value(0), max_size(0) {}
};

class vm_executable;

class script_object
{
public:
  class instance;
  typedef list<instance*> instance_list;
  typedef set<stringx> instance_name_list;

protected:
  stringx name;
  bool global_object;
#ifndef _RELEASE
  vm_symbol_list static_symbols;
  vm_symbol_list symbols;
#endif
  so_data_block static_data;
  int data_blocksize;
  vector<vm_executable*> funcs;
  instance_list instances;
#ifndef BUILD_BOOTABLE
  instance_name_list instance_names;
#endif

public:
  script_object();
};

script_object::script_object()
:   name(),
    global_object(false),
#ifndef _RELEASE
    static_symbols(),
    symbols(),
#endif
    static_data(),
    data_blocksize(0),
    funcs(),
    instances()
  {
  }
